import * as T from './vendor/three.module.js';
import {createSpider} from './spider-model.js';
export function createPrologue({done,say,sound}){
 const scene=new T.Scene();scene.background=new T.Color(0x728793);const camera=new T.PerspectiveCamera(70,innerWidth/innerHeight,.06,70);camera.rotation.order='YXZ';const group=new T.Group();scene.add(group);scene.add(new T.HemisphereLight(0xe1efff,0x6a5945,2));const lamp=new T.PointLight(0xffdec1,40,30);lamp.position.set(0,4,0);scene.add(lamp);const blockers=[],people=[];let phase='home',step=0,t=0,disaster=0,ended=false,spider;
 const tasks=[{x:-4,z:1,title:'כבה את השעון המעורר',line:'בוקר טוב! זה הבית שלך. אתה עובד כעוזר מחקר במעבדת העכבישים. היום הצוות יבדוק קורים חזקים לחילוץ אנשים. גש לארון הבגדים מימין והתארגן לעבודה.'},{x:5,z:4.3,title:'לבש בגדי עבודה',line:'לבשת את בגדי העבודה. עכשיו צריך לקחת את התיק ותג העובד.'},{x:4,z:2,title:'קח את התיק ותג העובד',line:'בתיק יש פנס ותג עובד. המעבדה נמצאת באחוזה ישנה מחוץ לעיר. קיבלת הודעה: ״נפגשים ליד תא 08״. כשאתה מוכן, גש לדלת שבין החלונות ולחץ E.'},{x:0,z:-6,title:'צא לעבודה',line:'בדרך לאחוזת המחקר…'}];
 function box(w,h,d,c,x,y,z,solid=false,parent=group){const m=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color:c,roughness:.72,metalness:c===0x52616a?.5:0}));m.position.set(x,y,z);parent.add(m);if(solid)blockers.push({x,z,w,d});return m;}
 function ball(r,c,x,y,z,parent=group){const m=new T.Mesh(new T.SphereGeometry(r,16,12),new T.MeshStandardMaterial({color:c,roughness:.65}));m.position.set(x,y,z);parent.add(m);return m;}
 function sign(text,x,y,z){const c=document.createElement('canvas');c.width=768;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='#26383c';ctx.fillRect(0,0,768,128);ctx.fillStyle='#f5e5b9';ctx.font='bold 38px Arial';ctx.textAlign='center';ctx.direction='rtl';ctx.fillText(text,384,78);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(new T.PlaneGeometry(3,.5),new T.MeshBasicMaterial({map:tex}));m.position.set(x,y,z);group.add(m);}
 function shell(){const floor=box(16,.2,15,0xbaa587,0,-.1,0);const grain=document.createElement('canvas');grain.width=256;grain.height=256;const gc=grain.getContext('2d');gc.fillStyle='#b59a74';gc.fillRect(0,0,256,256);for(let i=0;i<180;i++){gc.strokeStyle=i%3?'#a68b67':'#c6ad87';gc.beginPath();gc.moveTo(i*37%256,0);gc.lineTo(i*37%256+Math.sin(i)*4,256);gc.stroke();}for(let i=0;i<4;i++){gc.fillStyle='#685641';gc.fillRect(i*64,0,2,256);}const ft=new T.CanvasTexture(grain);ft.colorSpace=T.SRGBColorSpace;ft.wrapS=ft.wrapT=T.RepeatWrapping;ft.repeat.set(5,5);floor.material.map=ft;box(16,.2,15,0xb6b7ad,0,4.3,0);for(const x of [-8,8])box(.2,4.3,15,0xa5b1ad,x,2.15,0);for(const z of [-7.5,7.5])box(16,4.3,.2,0x9daaa6,0,2.15,z);for(const x of [-5,5]){box(2.4,2,.05,0x94bed4,x,2.5,-7.36);box(.08,2,.08,0x504d45,x,2.5,-7.3);}for(let z=-7;z<8;z++)box(16,.005,.02,0x4b504b,0,.006,z);}
 function home(){shell();
 // Warm apartment details leave a wide walking lane through the centre.
 box(4.4,.018,5.5,0xa76c48,0,.02,1.2);for(const x of [-2.1,2.1])box(.07,.02,5.3,0xe0c396,x,.035,1.2);
 box(3.2,.5,1,0x496e6a,-5,.25,-3.8,true);box(3.2,.9,.25,0x395d59,-5,.8,-4.25);for(const x of [-6.55,-3.45])box(.2,.7,1.1,0x395d59,x,.5,-3.8);for(const x of [-5.8,-4.8])box(.65,.18,.65,0xd6b477,x,.6,-3.8);
 box(1.8,.09,.9,0x856245,-5,.55,-2.1,true);for(const x of [-5.7,-4.3])for(const z of [-2.4,-1.8])box(.07,.55,.07,0x4b3c2e,x,.275,z);box(.4,.05,.3,0x8c3933,-5,.64,-2.1);
 for(const x of [-6.5,6.5]){box(.38,.6,.38,0x9c7251,x,.3,-6.4);for(let i=0;i<8;i++){const leaf=ball(.24,0x52754a,x+Math.sin(i*2)*.25,.85+i*.06,-6.4+Math.cos(i*2)*.25);leaf.scale.set(.6,1.5,.6);}}
 for(const x of [-5,5]){for(const dx of [-1.35,1.35])box(.35,2.5,.16,0xd1c5a7,x+dx,2.4,-7.18);box(2.9,.1,.15,0x806647,x,3.7,-7.15);box(2.2,.02,1.6,0xc3aa75,x,.025,-5.9);}
 for(const x of [-7.85,7.85])box(.08,.16,14.5,0xeee1c3,x,.08,0);
 box(2.4,.07,.55,0x836243,4,2.2,1);for(let i=0;i<8;i++)box(.16,.3+(i%3)*.06,.24,[0x536f75,0xad7950,0x67784e][i%3],3.2+i*.2,2.4,1);
 sign('בגדי עבודה',5,3,5.35);sign('תיק ותג עובד',4,1.9,.7);sign('השעון ליד המיטה',-5,1.5,1.9);
box(1.8,2.6,.7,0x64513e,5,1.3,5.8,true);box(.05,2.5,.04,0x302b27,5,1.3,5.42);ball(.045,0xb4a17d,4.85,1.3,5.4);box(2.5,.65,3.8,0x604b3a,-5,.325,4.5,true);box(2.4,.25,3.7,0xa9b7ad,-5,.8,4.5);box(1.8,.2,.7,0xe1d6bb,-5,1,3);box(.7,.8,.7,0x70573e,-5,.4,2,true);box(.3,.15,.12,0x30383c,-5,.88,2);box(2,.1,.8,0x684e35,4,.85,1,true);box(.5,.5,.25,0x3b5659,4,1.15,1);box(.18,.03,.25,0xe6d4a2,4.5,.93,1);box(1.7,3,.12,0x57442c,0,1.5,-7.3);sign('בית • בוקר הניסוי',0,3.5,-7.15);camera.position.set(0,1.65,5);}
 function scientist(name,x,z,skin,hair){const g=new T.Group();g.position.set(x,0,z);group.add(g);box(.55,.8,.3,0xe1e5dc,0,1.15,0,false,g);box(.3,.2,.32,0x415b67,0,1.5,.02,false,g);ball(.19,skin,0,1.83,0,g);ball(.19,hair,0,1.94,-.03,g);for(const side of [-1,1]){box(.15,.7,.2,0x303d48,side*.17,.4,0,false,g);box(.18,.1,.32,0x293235,side*.17,.05,.06,false,g);box(.13,.63,.14,0xd7dfd7,side*.36,1.18,0,false,g);ball(.08,skin,side*.36,.83,0,g);ball(.025,0x202726,side*.065,1.85,.175,g);}box(.09,.12,.02,0x73a0ae,.15,1.35,.16,false,g);ball(.045,skin,0,1.8,.19,g);box(.08,.018,.015,0x83594e,0,1.73,.18,false,g);box(.16,.1,.03,0xc7d1c9,-.14,1.24,.17,false,g);for(let j=0;j<4;j++)ball(.015,0x78847f,.03,1.02+j*.12,.17,g);for(const side of [-1,1]){for(let j=0;j<3;j++)box(.025,.08,.025,skin,side*.36+(j-1)*.025,.77,.02,false,g);const rim=new T.Mesh(new T.TorusGeometry(.065,.009,6,16),new T.MeshStandardMaterial({color:0x485453,metalness:.6,roughness:.4}));rim.position.set(side*.075,1.85,.19);g.add(rim);}box(.035,.012,.015,0x485453,0,1.85,.195,false,g);people.push(g);sign(name,x,2.45,z);blockers.push({x,z,w:.9,d:.7});}
 function lab(){group.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});group.clear();blockers.length=0;phase='lab';step=0;shell();scene.background.set(0x314b59);lamp.color.set(0xd3e8ed);scientist('ד״ר נועה • מנהלת הניסוי',-5,-1,0xc39576,0x493728);scientist('ד״ר אמיר • חוקר קורים',5,-1,0x9b6b4c,0x292524);scientist('ד״ר מאיה • בטיחות',-5,-5,0xe1b397,0x805740);scientist('ד״ר יואב • בקרת מערכות',5,-5,0xc69a7d,0x4d4944);for(const x of [-5,5]){box(2.2,.12,1,0x52616a,x,.9,-3,true);box(.8,.5,.08,0x283b42,x,1.2,-3.25);box(.7,.38,.02,0x71b8b3,x,1.2,-3.19);}box(2.8,.45,2.2,0x52616a,0,.225,-4,true);const glass=box(2.8,2,2.2,0x83b4c0,0,1.5,-4);glass.material.transparent=true;glass.material.opacity=.16;glass.material.depthWrite=false;spider=createSpider(group);spider.g.position.set(0,.5,-4);spider.g.scale.setScalar(.23);sign('ניסוי 08 • תא המחקר',0,3.2,-5.5);box(.8,.8,.5,0x52616a,1.9,.4,-2,true);ball(.13,0xb74735,1.9,.9,-2);const robot=new T.Group();robot.position.set(-2.8,0,1);group.add(robot);box(.6,.8,.4,0x7e8e88,0,1.15,0,false,robot);box(.5,.35,.4,0x879990,0,1.8,0,false,robot);for(const x of [-.18,.18]){box(.17,.7,.2,0x536763,x,.4,0,false,robot);ball(.06,0x91d4bd,x*.6,1.82,.23,robot);}sign('יחידת תחזוקה 08',-2.8,2.5,1);camera.position.set(0,1.65,5);say('רובוט: בוקר טוב! ברוך הבא לאחוזת המחקר. ד״ר נועה מחכה לך משמאל.');}
 const labTasks=[{x:-5,z:.2,title:'דבר עם ד״ר נועה',line:'נועה: אנחנו מנסים ליצור קורי משי לחילוץ אנשים. אמיר יסביר לך איך מודדים את החוזק.'},{x:5,z:.2,title:'דבר עם ד״ר אמיר',line:'אמיר: החוט הזה יכול לשאת משקל עצום. אבל העכביש גדל מאז אתמול. מאיה ביקשה לבדוק אותו שוב.'},{x:-5,z:-4,title:'קבל אישור מד״ר מאיה',line:'מאיה: בדיקה קצרה בלבד. אם הגודל משתנה, עוצרים מיד. יואב הכין את המחשב שמימין.'},{x:5,z:-2,title:'בדוק את המחשב',line:'יואב: החיישנים מוכנים. עבור לכפתור שליד התא והתחל בדיקת משי.'},{x:1.9,z:-1,title:'הפעל את בדיקת המשי',line:'מאיה: רגע… המדידה עולה מהר מדי. תעצרו את ההזנה!'}];
 function target(){return (phase==='home'?tasks:labTasks)[step];}
 function interact(){if(disaster||ended)return;const q=target();if(Math.hypot(camera.position.x-q.x,camera.position.z-q.z)>2)return;say(q.line);sound();step++;if(phase==='home'&&step===tasks.length)lab();else if(phase==='lab'&&step===labTasks.length){disaster=.01;}}
 function update(dt,keys,yaw,pitch,touch){t+=dt;if(ended)return;if(disaster){disaster+=dt;lamp.color.set(0xb83d24);lamp.intensity=12;spider.g.scale.setScalar(.23+Math.min(disaster/7,1)*1.1);if(disaster>2&&disaster-dt<=2)say('יואב: הזכוכית נסדקת! כולם לחדר הבקרה!');if(disaster>5&&disaster-dt<=5)say('רובוט: סגרתי את דלת החירום. הישאר כאן עד שאחזור.');document.getElementById('intro-fade').style.opacity=String(Math.min(1,Math.max(0,(disaster-4)/2)));if(disaster>7){document.getElementById('intro-line').hidden=false;document.getElementById('intro-line').textContent='כעבור שעות… הרובוט העביר אותך למבואת האחוזה. זהו בית העכביש. הצוות נעלם והיציאה חסומה. עליך למצוא גרזן ולברוח.';}if(disaster>11){finish();return;}}else{let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-(touch?.y||0),r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+(touch?.x||0);const len=Math.max(1,Math.hypot(f,r));const dx=(r*Math.cos(yaw)-f*Math.sin(yaw))*dt*3/len,dz=(-r*Math.sin(yaw)-f*Math.cos(yaw))*dt*3/len;const clear=(x,z)=>Math.abs(x)<7.6&&Math.abs(z)<7.1&&!blockers.some(b=>Math.abs(x-b.x)<b.w/2+.3&&Math.abs(z-b.z)<b.d/2+.3);if(clear(camera.position.x+dx,camera.position.z))camera.position.x+=dx;if(clear(camera.position.x,camera.position.z+dz))camera.position.z+=dz;const q=target();document.getElementById('intro-task').textContent=(phase==='home'?'בוקר בבית • ':'יום עבודה • ')+q.title+' • '+Math.ceil(Math.hypot(camera.position.x-q.x,camera.position.z-q.z))+' מטר';document.getElementById('intro-prompt').textContent=Math.hypot(camera.position.x-q.x,camera.position.z-q.z)<2?'E • '+q.title:'WASD לתנועה • עכבר למבט';}camera.rotation.set(pitch,yaw,0);for(let i=0;i<people.length;i++)people[i].rotation.y=Math.sin(t*.35+i)*.12;spider?.animate(t,dt,false,'patrol');}
 function finish(){if(ended)return;ended=true;document.getElementById('intro').hidden=true;group.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});done();}
 home();return{scene,camera,update,interact,finish,get phase(){return phase;},get step(){return step;},target};
}
